#!/usr/bin/env node

/**
 * P1-3 개선: GOGS 저장소 동적 조회로 동기화
 *
 * 전략:
 * 1. gogs-all-repos.json 로드 (kim 계정의 모든 저장소)
 * 2. projects.json과 이름으로 매칭
 * 3. 매칭된 프로젝트에 repo_url 추가
 * 4. sync-updated-at.js 재실행
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// 홈 디렉토리의 kim-project-cli에서 GOGS 저장소 목록 로드
const gogsListPath = path.join(process.env.HOME || '/root', 'kim-project-cli', 'gogs-all-repos.json');

function normalizeProjectName(name) {
  return (name || '')
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, '') // 숫자, 하이픈만 남김
    .replace(/^freelang/, '') // freelang- 제거
    .replace(/^fl/, '');
}

function findGogsRepo(projectName, gogsRepos) {
  const normalized = normalizeProjectName(projectName);

  // 정확한 이름 매칭
  const exact = gogsRepos.find(r => r.name === projectName);
  if (exact) return exact;

  // 정규화된 이름으로 매칭
  const normalized2 = gogsRepos.find(r =>
    normalizeProjectName(r.name) === normalized
  );
  if (normalized2) return normalized2;

  // 부분 매칭 (freelang-blockchain-dpos → blockchain-dpos)
  const partial = gogsRepos.find(r =>
    r.name.toLowerCase().includes(normalized) ||
    normalized.includes(normalizeProjectName(r.name))
  );
  if (partial) return partial;

  return null;
}

async function syncWithGogsLookup(projectsJsonPath) {
  console.log('📡 Loading GOGS repository list...\n');

  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  if (!fs.existsSync(gogsListPath)) {
    console.error(`❌ GOGS list not found: ${gogsListPath}`);
    console.error('   Run: node ~/kim-project-cli/gogs-lookup-api.js');
    process.exit(1);
  }

  const projectsData = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(projectsData) ? projectsData : projectsData.projects || [];

  const gogsData = JSON.parse(fs.readFileSync(gogsListPath, 'utf-8'));
  const gogsRepos = Array.isArray(gogsData) ? gogsData : gogsData.repos || [];

  console.log(`✅ Loaded ${projects.length} projects and ${gogsRepos.length} GOGS repositories\n`);

  let matched = 0;
  let unmatched = 0;

  // 각 프로젝트와 GOGS 저장소 매칭
  projects.forEach(project => {
    const gogsRepo = findGogsRepo(project.name, gogsRepos);

    if (gogsRepo) {
      project.repo_url = gogsRepo.url;
      project.gogs_path = gogsRepo.path;
      matched++;

      if (matched <= 5 || matched % 20 === 0) {
        console.log(`✅ [MATCHED] ${project.name} → ${gogsRepo.url}`);
      }
    } else {
      unmatched++;
      if (unmatched <= 3) {
        console.log(`❌ [NO MATCH] ${project.name}`);
      }
    }
  });

  console.log('\n' + '='.repeat(60));
  console.log('📊 Matching Summary:');
  console.log(`   ✅ Matched: ${matched}/${projects.length}`);
  console.log(`   ❌ Unmatched: ${unmatched}/${projects.length}`);
  console.log('='.repeat(60) + '\n');

  // 보강된 프로젝트 저장
  const outputPath = projectsJsonPath.replace('.json', '-with-gogs-urls.json');
  const output = Array.isArray(projectsData) ? projects : { ...projectsData, projects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`📁 Output: ${outputPath}`);
  console.log(`\n🔄 Next: Run sync-updated-at.js with this file`);
  console.log(`   node sync-updated-at.js ${outputPath}\n`);

  return { matched, unmatched, outputPath };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node sync-with-gogs-lookup.js <projects.json>');
  console.error('예제: node sync-with-gogs-lookup.js ~/kim-project-cli/projects.json');
  process.exit(1);
}

(async () => {
  try {
    const result = await syncWithGogsLookup(projectsJsonPath);
    console.log(`✨ GOGS 매칭 완료! ${result.matched}개 프로젝트 매칭됨`);
  } catch (error) {
    console.error('❌ 오류:', error.message);
    process.exit(1);
  }
})();

