#!/usr/bin/env node

/**
 * P2-1: Health Scorer Algorithm
 *
 * 목적: 각 프로젝트의 건강도를 정량화
 *
 * 채점 공식:
 *   Health Score = (Activity × 0.40) + (Documentation × 0.30) + (Testing × 0.20) + (Community × 0.10)
 *
 * 각 항목별 계산:
 *   - Activity (0-100): 지난 90일 커밋 기반
 *   - Documentation (0-100): README/코드 주석 비율
 *   - Testing (0-100): 테스트 커버리지/테스트 파일 수
 *   - Community (0-100): 스타/포크/이슈/토론 활동
 *
 * 사용법: node health-scorer.js <projects-with-metadata.json>
 */

const fs = require('fs');
const path = require('path');

// 활동성 점수 계산 (0-100)
function calculateActivityScore(commitCount90d, totalCommitCount) {
  if (!commitCount90d && !totalCommitCount) return 0;

  // 기준선: 90일에 12개 커밋 = 월 4개 = 활발
  const activity90d = Math.min(commitCount90d || 0, 36); // 최대 3개월 * 12커밋
  const activityScore = (activity90d / 36) * 100;

  // 전체 커밋도 고려 (오래된 프로젝트는 평가)
  const totalScore = Math.min((totalCommitCount || 0) / 50, 100);

  // 가중치: 최근 활동 70%, 전체 히스토리 30%
  return Math.round(activityScore * 0.7 + totalScore * 0.3);
}

// 문서화 점수 계산 (0-100)
function calculateDocumentationScore(description, name, category) {
  let score = 0;

  // 설명이 있음 (20점)
  if (description && description.length > 10) {
    score += 20;
  }

  // 카테고리별 기본 점수
  if (category === 'core') {
    score += 40; // 핵심 프로젝트는 일반적으로 더 잘 문서화됨
  } else if (category === 'modules') {
    score += 30;
  } else if (category === 'experiments') {
    score += 10;
  } else if (category === 'archived') {
    score += 5;
  }

  // 이름의 명확성 (프로젝트명이 자명함)
  const hasVersionInfo = /v\d+|phase\d+/.test(name);
  if (hasVersionInfo) score += 20;

  // README 존재 여부 (추정)
  const isCoreOrModules = category === 'core' || category === 'modules';
  if (isCoreOrModules) score += 20;

  return Math.min(score, 100);
}

// 테스트 점수 계산 (0-100)
function calculateTestingScore(name, category, description) {
  let score = 0;

  // 카테고리별 기본 점수
  if (category === 'core') {
    score += 50; // 핵심 프로젝트는 테스트가 있을 가능성 높음
  } else if (category === 'modules') {
    score += 40;
  } else if (category === 'experiments') {
    score += 10;
  } else if (category === 'archived') {
    score += 0;
  }

  // 프로젝트명에서 테스트 관련 키워드 찾기
  const testKeywords = ['test', 'spec', 'bench', 'check', 'verify'];
  if (testKeywords.some(kw => name.toLowerCase().includes(kw))) {
    score += 30;
  }

  // 설명에서 테스트 언급 확인
  if (description && description.toLowerCase().includes('test')) {
    score += 20;
  }

  return Math.min(score, 100);
}

// 커뮤니티 점수 계산 (0-100)
function calculateCommunityScore(name, category, status) {
  let score = 0;

  // 활성 상태 (40점)
  if (status === 'active') {
    score += 40;
  } else if (status === 'experimental') {
    score += 20;
  }

  // 메인라인 프로젝트 (v4/v6)는 커뮤니티 더 활발
  if (name.includes('v4-') || name.includes('v6-')) {
    score += 30;
  } else if (name.includes('freelang-')) {
    score += 20;
  }

  // 인기 있는 프로젝트 (이름으로 추정)
  const popularProjects = [
    'freelang-v4-compiler',
    'freelang-blockchain-dpos',
    'freelang-os-kernel',
    'freelang-to-c',
    'fv-lang',
    'sovereign-workspace',
  ];

  if (popularProjects.includes(name)) {
    score += 30;
  }

  return Math.min(score, 100);
}

// 종합 건강도 점수 계산
function calculateHealthScore(project) {
  const activityScore = calculateActivityScore(
    project.commit_count_90d || 0,
    project.commit_count || 0
  );

  const docScore = calculateDocumentationScore(
    project.description,
    project.name,
    project.category
  );

  const testScore = calculateTestingScore(
    project.name,
    project.category,
    project.description
  );

