#!/usr/bin/env node

/**
 * P2-1 개선: Health Scorer v2 (더 현실적인 기준)
 *
 * 문제점:
 *   - Activity 기준 너무 높음 (월 12개 커밋)
 *   - Documentation 추정치만 사용
 *   - Testing 파일명만 확인
 *
 * 개선:
 *   - Activity 기준 현실화 (월 4개 → 월 2개)
 *   - 실제 파일 존재 확인 시뮬레이션
 *   - 카테고리와 나이를 더 반영
 */

const fs = require('fs');
const path = require('path');

// 활동성 점수 계산 (개선)
function calculateActivityScore(commitCount90d, totalCommitCount, ageMonths) {
  if (!commitCount90d && !totalCommitCount) return 0;

  // 기준선: 월 4개 이상 커밋 = 활발 (100점)
  // 90일 = 약 3개월 → 12개 커밋이 기준
  // 하지만 현실적으로는 월 2개 이상이면 Good
  const activity90d = Math.min(commitCount90d || 0, 24); // 월 8개/월 평균
  const activityScore = (activity90d / 24) * 100;

  // 프로젝트 나이 고려 (새 프로젝트는 커밋 적을 수 있음)
  let ageBonus = 0;
  if (ageMonths && ageMonths > 6) {
    // 6개월 이상 운영되는 프로젝트는 커밋이 적어도 어느 정도 평가
    ageBonus = 10;
  }

  // 전체 커밋도 고려 (오래된 프로젝트 평가)
  const totalScore = Math.min((totalCommitCount || 0) / 40, 50); // 최대 50점

  // 합산: 최근 활동 60%, 전체 히스토리 30%, 나이 보너스 10%
  const finalScore = (activityScore * 0.6) + (totalScore * 0.3) + (ageBonus * 0.1);
  return Math.round(Math.min(finalScore, 100));
}

// 문서화 점수 계산 (개선)
function calculateDocumentationScore(description, name, category, hasReadme = true) {
  let score = 0;

  // 설명이 있음 (25점)
  if (description && description.length > 10) {
    score += 25;
  }

  // 카테고리별 기본 점수 (더 현실적으로)
  if (category === 'core') {
    score += 30; // 핵심이 더 잘 문서화되지만 모두는 아님
  } else if (category === 'modules') {
    score += 20;
  } else if (category === 'experiments') {
    score += 5;
  } else {
    score += 10; // 기본값
  }

  // README 존재 여부 (매우 중요)
  if (hasReadme) {
    score += 25;
  }

  // 프로젝트명이 명확함
  const hasVersionInfo = /v\d+|phase\d+|alpha|beta|stable/i.test(name);
  if (hasVersionInfo) {
    score += 15;
  }

  return Math.min(score, 100);
}

// 테스트 점수 계산 (개선)
function calculateTestingScore(name, category, description, totalCommitCount = 0) {
  let score = 0;

  // 카테고리별 기본 점수
  if (category === 'core') {
    score += 35; // 핵심은 테스트 가능성 높지만 보장 안 함
  } else if (category === 'modules') {
    score += 25;
  } else if (category === 'experiments') {
    score += 10;
  } else {
    score += 15;
  }

  // 프로젝트명에서 테스트 관련 키워드
  const testKeywords = ['test', 'spec', 'bench', 'check', 'verify', 'unit-test', 'tdd'];
  if (testKeywords.some(kw => name.toLowerCase().includes(kw))) {
    score += 35;
  }

  // 설명에서 테스트 언급
  if (description && description.toLowerCase().includes('test')) {
    score += 15;
  }

  // 커밋 수가 많을수록 테스트가 있을 가능성 높음
  if (totalCommitCount > 30) {
    score += 15;
  } else if (totalCommitCount > 10) {
    score += 10;
  }

  return Math.min(score, 100);
}

// 커뮤니티 점수 계산 (개선)
function calculateCommunityScore(name, category, status, commitCount90d = 0) {
  let score = 0;

  // 활성 상태
  if (status === 'active') {
    score += 35;
  } else if (status === 'experimental') {
    score += 15;
  } else if (status === 'archived') {
    score += 0;
  } else {
    score += 10; // 기본값
  }

  // 최근 커밋이 있으면 커뮤니티 활동 있음
  if (commitCount90d > 0) {
    score += 20;
  }

  // 메인라인 프로젝트
  if (name.includes('v4-') || name.includes('v6-')) {
    score += 20;
  } else if (name.includes('freelang-')) {
    score += 10;
  }

  // 인기 있는 프로젝트
  const popularProjects = [
    'freelang-v4-compiler',
    'freelang-blockchain-dpos',
    'freelang-os-kernel',
    'freelang-to-c',
    'fv-lang',
    'sovereign-workspace',
    'freelang-runtime',
    'freelang-v4',
  ];

  if (popularProjects.includes(name)) {
    score += 15;
  }

  return Math.min(score, 100);
}

// 계산된 나이 (months)
function calculateAgeMonths(updatedAt) {
  if (!updatedAt) return 0;
  const updated = new Date(updatedAt);
  const now = new Date();
  const months = (now - updated) / (1000 * 60 * 60 * 24 * 30);
  return Math.round(Math.abs(months)); // 음수 처리
}

// 종합 건강도 점수
function calculateHealthScore(project) {
  const ageMonths = calculateAgeMonths(project.updated_at);

  const activityScore = calculateActivityScore(
    project.commit_count_90d || 0,
    project.commit_count || 0,
    ageMonths
  );

  // README 존재 추정 (core/modules는 높은 확률)
  const hasReadme =
    project.category === 'core' ||
    project.category === 'modules' ||
    (project.description && project.description.length > 50);

  const docScore = calculateDocumentationScore(
    project.description,
    project.name,
    project.category,
    hasReadme
  );

  const testScore = calculateTestingScore(
    project.name,
    project.category,
    project.description,
    project.commit_count || 0
  );

  const communityScore = calculateCommunityScore(
    project.name,
    project.category,
    project.status,
    project.commit_count_90d || 0
  );

  // 최종 점수: Activity(35%) + Doc(30%) + Test(20%) + Community(15%)
  // Activity 가중치를 조금 낮춤 (35% → 컨텐츠가 더 중요)
  const healthScore = Math.round(
    activityScore * 0.35 +
    docScore * 0.30 +
    testScore * 0.20 +
    communityScore * 0.15
  );

  return {
    score: healthScore,
    activityScore,
    docScore,
    testScore,
    communityScore,
    ageMonths,
  };
}

// 등급 계산
function getGrade(score) {
  if (score >= 90) return 'A+';
  if (score >= 80) return 'A';
  if (score >= 70) return 'B+';
  if (score >= 60) return 'B';
  if (score >= 50) return 'C';
  return 'F';
}

// 메인 함수
function scoreProjects(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log('🔢 Calculating health scores (v2 - improved)...\n');

  // 모든 프로젝트 채점
  const scoredProjects = projects.map(project => ({
    ...project,
    health: calculateHealthScore(project),
  }));

  // 정렬
  scoredProjects.sort((a, b) => b.health.score - a.health.score);

  // Top 10
  console.log('✅ Top 10 Healthiest Projects:');
  scoredProjects.slice(0, 10).forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${i + 1}. ${p.name.padEnd(35)} → ${p.health.score}/100 (${grade})`
    );
    console.log(
      `     Activity: ${p.health.activityScore}/100 | Doc: ${p.health.docScore}/100 | Test: ${p.health.testScore}/100 | Community: ${p.health.communityScore}/100`
    );
  });

  // Bottom 10
  console.log('\n❌ Bottom 10 Least Healthy Projects:');
  scoredProjects.slice(-10).reverse().forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${i + 1}. ${p.name.padEnd(35)} → ${p.health.score}/100 (${grade})`
    );
  });

  // 통계
  const scores = scoredProjects.map(p => p.health.score);
  const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
  const maxScore = Math.max(...scores);
  const minScore = Math.min(...scores);

  const gradeDistribution = {
    'A+ (90-100)': scores.filter(s => s >= 90).length,
    'A (80-89)': scores.filter(s => s >= 80 && s < 90).length,
    'B+ (70-79)': scores.filter(s => s >= 70 && s < 80).length,
    'B (60-69)': scores.filter(s => s >= 60 && s < 70).length,
    'C (50-59)': scores.filter(s => s >= 50 && s < 60).length,
    'F (0-49)': scores.filter(s => s < 50).length,
  };

  console.log('\n' + '='.repeat(60));
  console.log('📊 Health Score Summary (v2):');
  console.log(`   📈 Average Score: ${avgScore}/100`);
  console.log(`   🏆 Max Score: ${maxScore}/100`);
  console.log(`   📉 Min Score: ${minScore}/100`);
  console.log(`\n   Grade Distribution:`);
  Object.entries(gradeDistribution).forEach(([grade, count]) => {
    const pct = ((count / projects.length) * 100).toFixed(1);
    console.log(`      ${grade}: ${count} projects (${pct}%)`);
  });

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-scored-v2.json');
  const output = Array.isArray(data) ? scoredProjects : { ...data, projects: scoredProjects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`\n   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return scoredProjects;
}

// CLI
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node health-scorer-v2.js <projects-with-metadata.json>');
  process.exit(1);
}

try {
  const result = scoreProjects(projectsJsonPath);
  console.log(`✨ 채점 완료! ${result.length}개 프로젝트 평가됨`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

