#!/usr/bin/env node

/**
 * P2-1 최종 버전: Health Scorer (현실적 기준)
 *
 * 핵심 변경:
 * 1. Activity는 "90일 커밋 여부"로 단순화 (정확한 수치 불가)
 * 2. 프로젝트 나이와 설명/카테고리를 더 중시
 * 3. F 등급은 "완전히 버려진" 프로젝트만 (archived + no activity)
 */

const fs = require('fs');
const path = require('path');

// 활동성 점수 (0-100)
function calculateActivityScore(commitCount90d, ageMonths, status) {
  // 1. Status 확인
  if (status === 'archived') {
    return 5; // 아카이브됨
  }

  if (status === 'experimental') {
    return 30; // 실험 단계는 낮지만 완전히 낮지 않음
  }

  // 2. 최근 90일 커밋 여부 (정확한 수는 신뢰 불가)
  if (commitCount90d && commitCount90d > 0) {
    // 최근에 어떤 커밋이 있으면 최소 50점
    return 50;
  }

  // 3. 나이 고려 (새 프로젝트일 수 있음)
  if (ageMonths && ageMonths < 3) {
    return 35; // 3개월 미만이면 활동 중일 가능성
  }

  if (ageMonths && ageMonths > 24) {
    return 20; // 2년 이상 활동 없으면 낮음
  }

  // 기본값: 활동 미확인
  return 30;
}

// 문서화 점수 (0-100)
function calculateDocumentationScore(description, name, category) {
  let score = 0;

  // 1. 설명이 있음 (중요!)
  if (description && description.length > 10) {
    score += 40;
  }

  // 2. 카테고리별
  if (category === 'core') {
    score += 35;
  } else if (category === 'modules') {
    score += 25;
  } else if (category === 'experiments') {
    score += 10;
  } else {
    score += 15;
  }

  // 3. 이름이 명확함
  if (/v\d+|phase\d+|alpha|beta|stable/i.test(name)) {
    score += 10;
  }

  return Math.min(score, 100);
}

// 테스트 점수 (0-100)
function calculateTestingScore(name, category, description, commitCount) {
  let score = 0;

  // 1. 카테고리별 기본 점수
  if (category === 'core') {
    score += 40;
  } else if (category === 'modules') {
    score += 30;
  } else if (category === 'experiments') {
    score += 10;
  } else {
    score += 15;
  }

  // 2. 이름에 테스트 키워드
  if (/test|spec|bench|verify/i.test(name)) {
    score += 30;
  }

  // 3. 설명에 테스트 언급
  if (description && /test|unit|coverage|assert/i.test(description)) {
    score += 15;
  }

  // 4. 활발한 프로젝트 (많은 커밋)는 테스트가 있을 가능성
  if (commitCount > 20) {
    score += 15;
  }

  return Math.min(score, 100);
}

// 커뮤니티 점수 (0-100)
function calculateCommunityScore(name, category, status, commitCount90d, description) {
  let score = 0;

  // 1. Status
  if (status === 'active') {
    score += 30;
  } else if (status === 'experimental') {
    score += 10;
  }

  // 2. 메인라인 프로젝트
  if (/v4|v6|compiler|runtime|kernel|blockchain/i.test(name)) {
    score += 25;
  } else if (/freelang|sovereign/i.test(name)) {
    score += 15;
  }

  // 3. 최근 커밋
  if (commitCount90d > 0) {
    score += 20;
  }

  // 4. 설명이 좋으면 커뮤니티 관심 높음
  if (description && description.length > 50) {
    score += 10;
  }

  return Math.min(score, 100);
}

// 나이 계산
function calculateAgeMonths(updatedAt) {
  if (!updatedAt) return 0;
  const updated = new Date(updatedAt);
  const now = new Date();
  const months = (now - updated) / (1000 * 60 * 60 * 24 * 30);
  return Math.round(Math.abs(months));
}

// 건강도 계산
function calculateHealthScore(project) {
  const ageMonths = calculateAgeMonths(project.updated_at);

  const activityScore = calculateActivityScore(
    project.commit_count_90d,
    ageMonths,
    project.status
  );

  const docScore = calculateDocumentationScore(
    project.description,
    project.name,
    project.category
  );

  const testScore = calculateTestingScore(
    project.name,
    project.category,
    project.description,
    project.commit_count || 0
  );

  const communityScore = calculateCommunityScore(
    project.name,
    project.category,
    project.status,
    project.commit_count_90d || 0,
    project.description
  );

  // 최종 가중치: Activity(25%) + Doc(40%) + Test(20%) + Community(15%)
  // 문서화를 가장 중요하게! (실제로 측정 가능)
  const healthScore = Math.round(
    activityScore * 0.25 +
    docScore * 0.40 +
    testScore * 0.20 +
    communityScore * 0.15
  );

  return {
    score: healthScore,
    activityScore,
    docScore,
    testScore,
    communityScore,
    ageMonths,
  };
}

// 등급
function getGrade(score) {
  if (score >= 90) return 'A+';
  if (score >= 80) return 'A';
  if (score >= 70) return 'B+';
  if (score >= 60) return 'B';
  if (score >= 50) return 'C';
  if (score >= 40) return 'D';
  return 'F';
}

// 메인
function scoreProjects(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log('🔢 Calculating health scores (Realistic Edition)...\n');

  const scoredProjects = projects.map(project => ({
    ...project,
    health: calculateHealthScore(project),
  }));

  scoredProjects.sort((a, b) => b.health.score - a.health.score);

  // Top 10
  console.log('✅ Top 10 Healthiest Projects:');
  scoredProjects.slice(0, 10).forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${i + 1}. ${p.name.padEnd(35)} → ${p.health.score}/100 (${grade})`
    );
    console.log(
      `     Doc: ${p.health.docScore}/100 | Activity: ${p.health.activityScore}/100`
    );
  });

  // Bottom 10
  console.log('\n❌ Bottom 10 Least Healthy Projects:');
  scoredProjects.slice(-10).reverse().forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${i + 1}. ${p.name.padEnd(35)} → ${p.health.score}/100 (${grade})`
    );
  });

  // 통계
  const scores = scoredProjects.map(p => p.health.score);
  const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
  const maxScore = Math.max(...scores);
  const minScore = Math.min(...scores);

  const gradeDistribution = {
    'A+ (90-100)': scores.filter(s => s >= 90).length,
    'A (80-89)': scores.filter(s => s >= 80 && s < 90).length,
    'B+ (70-79)': scores.filter(s => s >= 70 && s < 80).length,
    'B (60-69)': scores.filter(s => s >= 60 && s < 70).length,
    'C (50-59)': scores.filter(s => s >= 50 && s < 60).length,
    'D (40-49)': scores.filter(s => s >= 40 && s < 50).length,
    'F (0-39)': scores.filter(s => s < 40).length,
  };

  console.log('\n' + '='.repeat(70));
  console.log('📊 Health Score Summary (Realistic):');
  console.log(`   📈 Average Score: ${avgScore}/100`);
  console.log(`   🏆 Max Score: ${maxScore}/100`);
  console.log(`   📉 Min Score: ${minScore}/100\n`);
  console.log(`   Grade Distribution:`);
  Object.entries(gradeDistribution).forEach(([grade, count]) => {
    const pct = ((count / projects.length) * 100).toFixed(1);
    const bar = '█'.repeat(Math.round(count / 2));
    console.log(`      ${grade.padEnd(15)}: ${count.toString().padStart(3)} (${pct.padStart(5)}%) ${bar}`);
  });

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-scored-realistic.json');
  const output = Array.isArray(data) ? scoredProjects : { ...data, projects: scoredProjects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`\n   📁 Output: ${outputPath}`);
  console.log('='.repeat(70) + '\n');

  return scoredProjects;
}

// CLI
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node health-scorer-realistic.js <projects-with-metadata-enhanced.json>');
  process.exit(1);
}

try {
  const result = scoreProjects(projectsJsonPath);
  console.log(`✨ 채점 완료! ${result.length}개 프로젝트 평가됨`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

