#!/usr/bin/env node

/**
 * P2-1 최종 버전: Health Scorer (커밋 활동 중심)
 *
 * 🔴 문제점:
 *   1. Status (archived/experimental) 라벨로 과도하게 저평가
 *   2. Category (experiments) 라벨로 부당하게 감점
 *   3. freelang-v6 (20 커밋) vs 1.1-rag (1 커밋) 둘다 36점 (말도 안됨!)
 *
 * ✅ 해결책:
 *   1. commit_count를 주요 지표로 (실제 활동 반영)
 *   2. Status/Category는 보너스만 주기 (페널티 X)
 *   3. 90일 활동 여부를 명시적으로 표시
 */

const fs = require('fs');
const path = require('path');

// 활동성 점수 (0-100) - 커밋 기반
function calculateActivityScore(commitCount, commitCount90d) {
  // 커밋 없으면 0점
  if (!commitCount) return 0;

  // 커밋 수: 30점 기본 + 최대 70점
  // 1 commit = 30점, 10 commits = 45점, 50+ commits = 100점
  const commitScore = Math.min(30 + (commitCount * 1.4), 100);

  // 90일 활동 보너스: +10점
  const bonus = (commitCount90d && commitCount90d > 0) ? 10 : 0;

  return Math.min(100, Math.round(commitScore + bonus));
}

// 문서화 점수 (0-100)
function calculateDocumentationScore(description, name, category) {
  let score = 0;

  // 1. 설명이 있으면 기본 20점
  if (description && description.length > 10) {
    score += 20;
  }

  // 2. 좋은 설명이면 추가 30점
  if (description && description.length > 50) {
    score += 30;
  }

  // 3. 카테고리별 보너스 (페널티 X!)
  if (category === 'core') {
    score += 20;
  } else if (category === 'modules') {
    score += 15;
  } else if (category === 'experiments' || category === 'archived') {
    score += 5; // 최소값, 페널티 아님
  }

  // 4. 버전명 명확하면 +10
  if (/v\d+|phase\d+|alpha|beta|stable/i.test(name)) {
    score += 10;
  }

  return Math.min(score, 100);
}

// 테스트 점수 (0-100)
function calculateTestingScore(name, description) {
  let score = 20; // 기본 20점

  // 이름에 test 키워드: +50점
  if (/test|spec|bench|verify|unit/.test(name.toLowerCase())) {
    score += 50;
  }

  // 설명에 test 언급: +20점
  if (description && /test|unit|coverage|assert/i.test(description)) {
    score += 20;
  }

  return Math.min(score, 100);
}

// 커뮤니티 점수 (0-100)
function calculateCommunityScore(name, description, commitCount) {
  let score = 20; // 기본 20점

  // v4/v6/compiler/kernel/runtime: +30점
  if (/v4|v6|compiler|kernel|runtime|blockchain/i.test(name)) {
    score += 30;
  }

  // freelang 관련: +15점
  if (/freelang|sovereign/i.test(name)) {
    score += 15;
  }

  // 많은 커밋: +20점
  if (commitCount && commitCount > 20) {
    score += 20;
  }

  // 좋은 설명: +10점
  if (description && description.length > 50) {
    score += 10;
  }

  return Math.min(score, 100);
}

// 건강도 계산 (최종)
function calculateHealthScore(project) {
  const activityScore = calculateActivityScore(
    project.commit_count || 0,
    project.commit_count_90d || 0
  );

  const docScore = calculateDocumentationScore(
    project.description,
    project.name,
    project.category
  );

  const testScore = calculateTestingScore(
    project.name,
    project.description
  );

  const communityScore = calculateCommunityScore(
    project.name,
    project.description,
    project.commit_count || 0
  );

  // 가중치: Activity(45%) + Doc(30%) + Test(15%) + Community(10%)
  // Activity를 최우선! (실제 활동이 가장 중요)
  const healthScore = Math.round(
    activityScore * 0.45 +
    docScore * 0.30 +
    testScore * 0.15 +
    communityScore * 0.10
  );

  return {
    score: healthScore,
    activityScore,
    docScore,
    testScore,
    communityScore,
  };
}

// 등급
function getGrade(score) {
  if (score >= 90) return 'A+';
  if (score >= 80) return 'A';
  if (score >= 70) return 'B+';
  if (score >= 60) return 'B';
  if (score >= 50) return 'C';
  if (score >= 40) return 'D';
  return 'F';
}

// 메인
function scoreProjects(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log('🎯 Calculating health scores (Activity-First)...\n');

  const scoredProjects = projects.map(project => ({
    ...project,
    health: calculateHealthScore(project),
  }));

  scoredProjects.sort((a, b) => b.health.score - a.health.score);

  // Top 15
  console.log('🏆 Top 15 Healthiest Projects:');
  scoredProjects.slice(0, 15).forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${(i + 1).toString().padStart(2)}. ${p.name.padEnd(35)} → ${p.health.score.toString().padStart(2)}/100 (${grade})`
    );
  });

  // Bottom 10
  console.log('\n📉 Bottom 10 Projects:');
  scoredProjects.slice(-10).reverse().forEach((p, i) => {
    const grade = getGrade(p.health.score);
    console.log(
      `  ${(i + 1).toString().padStart(2)}. ${p.name.padEnd(35)} → ${p.health.score.toString().padStart(2)}/100 (${grade})`
    );
  });

  // 통계
  const scores = scoredProjects.map(p => p.health.score);
  const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
  const maxScore = Math.max(...scores);
  const minScore = Math.min(...scores);

  const gradeDistribution = {
    'A+ (90-100)': scores.filter(s => s >= 90).length,
    'A (80-89)': scores.filter(s => s >= 80 && s < 90).length,
    'B+ (70-79)': scores.filter(s => s >= 70 && s < 80).length,
    'B (60-69)': scores.filter(s => s >= 60 && s < 70).length,
    'C (50-59)': scores.filter(s => s >= 50 && s < 60).length,
    'D (40-49)': scores.filter(s => s >= 40 && s < 50).length,
    'F (0-39)': scores.filter(s => s < 40).length,
  };

  console.log('\n' + '='.repeat(70));
  console.log('📊 Health Score Summary (Activity-First):');
  console.log(`   📈 Average Score: ${avgScore}/100`);
  console.log(`   🏆 Max Score: ${maxScore}/100`);
  console.log(`   📉 Min Score: ${minScore}/100\n`);
  console.log(`   Grade Distribution:`);

  const total = projects.length;
  Object.entries(gradeDistribution).forEach(([grade, count]) => {
    const pct = ((count / total) * 100).toFixed(1);
    const bar = '█'.repeat(Math.round(count / 2));
    console.log(
      `      ${grade.padEnd(15)}: ${count.toString().padStart(3)} (${pct.padStart(5)}%) ${bar}`
    );
  });

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-scored-final.json');
  const output = Array.isArray(data) ? scoredProjects : { ...data, projects: scoredProjects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`\n   📁 Output: ${outputPath}`);
  console.log('='.repeat(70) + '\n');

  // 추가 인사이트
  console.log('📈 Key Insights:\n');

  const highActivity = scoredProjects.filter(p => p.commit_count && p.commit_count > 30);
  const noActivity = scoredProjects.filter(p => !p.commit_count || p.commit_count === 0);
  const wellDocumented = scoredProjects.filter(p => p.health.docScore >= 50);

  console.log(`✅ High Activity (>30 commits): ${highActivity.length} projects`);
  console.log(`   평균 점수: ${Math.round(highActivity.reduce((a, p) => a + p.health.score, 0) / highActivity.length)}/100`);

  console.log(`\n⚠️ No Activity (0 commits): ${noActivity.length} projects`);
  console.log(`   평균 점수: ${Math.round(noActivity.reduce((a, p) => a + p.health.score, 0) / noActivity.length)}/100`);

  console.log(`\n📚 Well-Documented (doc score >= 50): ${wellDocumented.length} projects`);
  console.log(`   평균 점수: ${Math.round(wellDocumented.reduce((a, p) => a + p.health.score, 0) / wellDocumented.length)}/100\n`);

  return scoredProjects;
}

// CLI
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node health-scorer-final.js <projects-enhanced.json>');
  process.exit(1);
}

try {
  const result = scoreProjects(projectsJsonPath);
  console.log(`✨ 평가 완료! ${result.length}개 프로젝트 점수 산출됨`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

